DROP TABLE listings;
DROP TABLE users;
PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (first_name varchar(255) NOT NULL, last_name varchar(255) NOT NULL, age INT NOT NULL, email varchar(255) NOT NULL, birth_date DATE NOT NULL);
CREATE TABLE listings (title varchar(255) NOT NULL, publish_date DATE NOT NULL, author_id INT NOT NULL, hourly_price FLOAT NOT NULL, subject varchar(255) NOT NULL, location varchar(255) NOT NULL, type varchar(255) NOT NULL, listing_id INT AUTO_INCREMENT NOT NULL PRIMARY KEY, grade varchar(255) NOT NULL);
